from build import save
rows=[
(411,['刺刀血统护腕与史诗新装，萧御神器/魔龙血统公开，公众挖任务等信息并衍绯闻。下注1273亿对113亿，双方侯爵；禁药特殊道具，试探技能令萧推刺客职业。'],['名声从隐秘变公开且真假混杂。'],[],25175,25243),
(412,['双方冷却后全力，小技速攻耗防，互免控后血损。刺刀被瞬进追逼召影子战神，实际100–200%能力公众与萧仍当影子战士；萧暗影克制召比蒙。'],['预习机制升级；底牌逐层显。'],[],25247,25322),
(413,['影战神130%本体同血技能，比蒙42血15000增防减速。双锁定连控被暗影克制解，使决斗转输出；刺刀小技不敌终结能量，萧比蒙配杀1号影、2本体控比蒙（不享免控）。'],['比蒙成为独立可攻弱点。'],[],25326,25392),
(414,['刺刀顶萧付5000血杀比蒙搏单挑，萧赞果决。末刺3000血耗萧5000，军中搏击与游戏血条差别被点明；骨龙毒咒配野性狂怒撕裂杀刺，萧余3000。尊败者使嘘声转双方掌声，刺解不败负累。'],['竞技已胜而非只占优势。'],[],25396,25481),
(415,['作者前瞻后来贼俱乐部聘双名誉主席。赌收益赵萧9.8亿、风野20亿实押赚196亿，公司版权影广收益最大；影视收入和风野10亿分红使萧近30亿。刺离魔域、被逐说是风野散谣，魔域求和附属条件尚谈。萧带赵避应酬，拟探索赴新星。'],['经济生计目标自觉完成；最高竞技尚未出现。'],[],25485,25528),
(416,['小雨接受移民告别，别墅吴照不售，给吴200万报恩、让妹向燕琳告别自己不见。恋人亲密但未最后一步。游戏交赵包和药，月夜给各雷尔起搏器死30分原地复每天1，萧收凤凰保末次。空间赴地下看攻城视频，换20万晶先沃克旅馆。'],['现实离别有具体安排；新增复生替代有限凤凰。'],[],25532,25599),
(417,['沃克引中位光明神艾斐尔。双子星两神王创光黑族，神族统各联盟；派人类找荒漠殿因神入乌会被察，不赐福给图、二神眷腰带各3组专家药。赵有真实新星战争医生经历，叙殖民灭原智慧族。萧推神养阵营争斗及终会干涉。'],['新任务已接；阵营斗争上方更大权力揭示。'],['神称萧公爵早于实际晋公爵。'],25603,25655),
(418,['付32000晶入乌黑日旷野设空间点。80普通龙岩蜥蜴60万血，萧打软腹与比蒙、赵双杖普通6500证实神言已持；三连爆转仇恨比蒙救，杀得经验荣装。十余同类追逃，地图实录。'],['神言杖交付虽省略使用已证；新图重新面临等级危险。'],[],25659,25721),
(419,['萧引16怪赵找石阵，遇自爆毒蟾高级解毒；窄阵卡体梦魇群杀，外围岩可被破需退深。巢引30多反复刷，2天萧60锁无转提示赵59；小雨转学已办。圣光城疏民两天后实际攻下驻军。'],['探索先补等级；攻城完成但战争未终。'],[],25725,25787),
(420,['拓图第六天山与阿兰德会晤和解撤圣光、地下要塞亦撤因。系统3天后全服竞各最多两项冠神器；萧1v1/赵2v2，赵另自愿风野50团。为赛前奖加速探，赵返练60萧独速，发现光暗门通两神界，80超阶执金攻击几死。'],['竞技与神任务后续相接；不等于已开新战。'],[],25791,25867),
(421,['执金电笼抓回，萧虚无逃后弱期记门坐标；百码斜柱引沙下墓样建筑，绕60强化鼠，视觉错觉光斑开门，致盲预先隐避70兽。系统确认荒漠殿，90半神祭，空间屏障及单向来路令找正门。'],['目标找到但撤离未成；误认墓不当事实。'],[],25871,25943),
(422,['祭方盒神王沃顿，主角不贪继续任务。正门20余祭堵，等冷却连位移药虚无冲，弱期出门被杀；半小时起搏原地复无耗凤凰。探3迪雅，赵60边境遭精灵追踪多人围、禁回城语音断，萧空间返赶救。'],['任务虽达标，生还依赖提前装备；救赵尚未到。'],[],25947,26023),
(423,['赵击偷袭贼招第七名团队30余追杀，以一敌六杀2控3，后方牧师群疗救；50人合围耗完控制后赵死，掉埃托斯格眷恋速语链，其实首赠珍藏。蓝月获链读字；萧见人欲亵尸愤怒下战书。'],['赵先有独立抵抗而非纯待救；旧物新危机。'],[],26028,26105),
(424,['萧先除追踪战复德鲁伊3再杀主牧，4死后隐退，敌缩阵不敢弃队。比蒙隐埋未出；萧再控冰法，敌协作快速反应。'],['以功能拆阵非只硬压50人。'],[],26109,26179),
(425,['满连击和能量秒冰法牧6死，但双盾破大地盾萧残5000以药+野狂冲。敌追，萧靠速度吃面包回、引猎离牧杀1宠杀2，追踪体系散。留最后牧给复活希望拖住队，23死。'],['游击需时间回复与敌不愿弃队，敌并非全无能。'],[],26183,26244),
(426,['29死后敌退出丛林识萧御。主角留50/60传说杀戮盛宴血腥屠戮不用。敌集中回城，埋比蒙群撞断所有卷轴，终50全杀。蓝月掉两装含项链，萧推主动送回，拟风野赠装谢。'],['全灭与链追回已成，非只宣言。'],[],26248,26315),
(427,['萧冷静反省因见亵渎而嫉愤过度；傲骨实际解团退出，公众猜萧大元帅（当时尚元帅）。赵起搏复、项链已交回。交艾斐尔地图得+1000血全技+1、天使戒适赵/艾神戒萧戴。知杀沃顿还毁荒漠本命骷髅，选竞技强者非个人续任，方盒猜测未定；克探图暂不交。'],['寻找任务领奖完成，后续神战仍未接；关系旧礼回收。'],[],26319,26383),
(428,['神赐转30万荣现165万差35万。竞技装备涨价、等级优势消。魔域正式同意附属风野，声称天使联盟90%地盘疑源误。赵团练高BOSS换装，萧探5迪雅交克得37万荣功1万，实际晋公爵大元帅、买勋和5下位神套PK等同属性，血27000加影子技能。'],['探索真正交完、荣衔晋升；套装非打BOSS万能。'],[],26387,26442),
(429,['二人换装拟重新磨合，下线小雨25向兄求赶50冰法追求者，兄先戏弄再应。为受照顾妹妹同学采购几无级稀装，穿20杂装赴约低调，保证仍胜。'],['宏大战后日常支线缓冲。'],[],26446,26513),
(430,['冰法洛城被轻装主角挑衅后怒，萧赌被打中即输，8秒六七技无伤杀。几同学识视频人物、小雨欢呼。'],['妹妹赌约本场已赢，但洛是否退未展。'],[],26517,26600),
]
d={
'worldbuilding':[['影子战神强度100–200%、实130%，本体同血技能；暗影克制只自体比蒙仍受控制。','fact',[412,25305,25306],[413,25326,25327],[413,25385,25387]],['起搏器每日一次死30分原地复，怪群里复仍会死；凤凰有限最后次被收起，422使用起搏未耗羽。','fact',[416,25570,25576],[422,25997,26003]],['光黑神族由两神王造双星，上方神控制阵营；不能赐福是隐蔽限制，神威不是本书任何任务万能解法。','fact',[417,25625,25635]],['大元帅五下位神套的等同属性主要PK，套控免使自控无效，技能与原装有取舍。','fact',[428,26431,26442]]],
'characters':[['刺刀输前以5000血换比蒙争单挑，败后解不败负担；主角尊敬而不让步，保败者行动价值。','fact',[414,25414,25424],[414,25462,25481]],['赵既开发练级又承担团队输出治疗，423独抗六人先杀2后被团协耗，不能摘要为只会待救。','fact',[418,25690,25707],[423,26036,26078]],['萧狂怒灭团后承认嫉妒使反应过头，这与尊刺刀及功利取奖构成不全善人性。','fact',[426,26269,26273],[427,26319,26325]],['小雨移民失落、同学帮助与游戏玩伴延续，使离旧生活不是只换富裕住所。','fact',[416,25532,25537],[419,25783,25785],[429,26464,26490]]],
'plot':[['影子支线预习后终敌升级成战神，原策略有效却仍需付比蒙代价，升级规则避免照抄前战。','inference',[412,25299,25308],[413,25385,25391],[414,25414,25424]],['竞技看似商业加温，后由艾斐尔说明实选使徒毁神本命；探索地图为集体后续任务前提。','fact',[420,25798,25815],[427,26369,26379]],['旧速语项链属性过时仍佩，死亡掉落、蓝月读铭、再交回，使数值最差转为关系最重。','inference',[423,26080,26090],[424,26109,26110],[426,26312,26315],[427,26335,26343]]],
'style':[['胜负用血条、技能剩余、物理控制和空间变化拆解；最后搏击说明现实与游戏生命规则差别。','inference',[413,25381,25391],[414,25443,25465]],['全灭报数、敌惧与猛虎羔羊比喻加强报复爽点，但反复贬敌与女性崇拜会压低复杂性。','inference',[424,26145,26175],[425,26237,26244],[426,26284,26293]],['幻视光斑开门用感官困难代替硬锁规则，开门致盲后又生新危险。','inference',[421,25913,25930]]],
'narrative':[['刺羽/风野两方观赛解释非对称声誉风险；公众技判数次失效而内行保判断差。','inference',[413,25328,25330],[414,25400,25424]],['神族放阵营争斗磨强是萧推断，后联盟停战被叙述归神操控；阶段不能提前当起初确定。','fact',[417,25645,25654],[420,25793,25796]],['419实际攻下城与420撤军和解是两事；415预言不能替前两事实。','fact',[415,25526,25528],[419,25785,25787],[420,25793,25797]]],
'dialogue':[['战后尊败者的公开话让嘘者闭嘴，主角态度给群众情绪重新定框。','inference',[414,25466,25481]],['玫瑰旅馆先等待NPC主动，再从目的地问句引内堂神，日常服务对话逐级揭权力。','inference',[416,25591,25599],[417,25603,25623]],['兄妹夸张互损和恋人吃饭提醒，让最高竞技后回到熟人尺度，减轻连续大场面。','inference',[429,26449,26484]]],
'pacing':[['刺刀竞技完全展开到濒血，财富政治结算后现实告别再入新图，高潮后换尺度而非即刻再战神。','inference',[414,25425,25481],[415,25488,25525],[416,25532,25538]],['新图先单怪、群追、地形刷级，再神门逃亡与封闭神殿，安全感逐级重置。','inference',[418,25678,25721],[419,25725,25765],[420,25834,25867],[422,25955,26003]],['连续探索后赵遇险插回旧大陆，情感线旧物回收与主线领奖衔接，避免地图说明长成纯设定。','inference',[422,26013,26023],[423,26080,26098],[427,26335,26356]]],
'themes':[['胜负不能取消努力尊严，刺刀得到竞技掌声却魔域政治仍受损，竞技价值和组织利益有裂缝。','inference',[414,25462,25481],[415,25513,25517]],['神与国家交战的背后是更大权力操纵，且417把现实新星殖民灭族与游戏征服并置；不能将殖民乐园当无损幸福。','inference',[417,25645,25654]],['资源型爱情与记忆型爱情不同：速语链因首赠保留，不是因比神器强；蓝月认为它最好属感情判断。','fact',[423,26083,26090],[427,26335,26343]]],
'continuity':[['417神称萧公爵，428才系统晋，先称呼与实际晋升不一致；公众427猜大元帅也不能提前实化。','fact',[417,25619,25619],[427,26330,26333],[428,26420,26422]],['411四系戒句主体萧御疑应萧翎；415拍刺刀肩风野回答、430萧称天使第一贼均源误名/阵营异常，勿新造身份。','fact',[411,25178,25179],[415,25506,25507],[430,26598,26600]],['423队长傲骨末写傲天，同一行为链记误称；428风野“整个天使联盟90%”与其邪恶阵营关系冲突须保留。','fact',[423,26070,26104],[428,26392,26394]],['方盒是否沃顿本命骷髅仍主角怀疑并自我否定，任务只给其在荒漠殿的推断位置。','fact',[421,25942,25943],[427,26372,26379]]],
}
